/* Device-local functional prototype. No server or external messages are implied. */
(() => {
  'use strict';
  const W=window.Workflow, $=s=>document.querySelector(s);
  let storage;try{storage=window.localStorage;}catch{/* session-only fallback */}
  let firstReset=false;try{firstReset=storage?.getItem(W.RESET_MARKER)!=='done';}catch{}
  const store=W.createStore(storage), root=$('#app');
  try{window.sessionStorage?.removeItem('lannpya.form-drafts');if(firstReset)window.sessionStorage?.removeItem('lannpya.form-drafts.v4');}catch{}
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const amount=x=>Number.isFinite(x)?`${x.toLocaleString()} MMK`:'Not confirmed';
  const pretty=x=>String(x||'').replaceAll('_',' ');
  const pill=(text,kind)=>`<span class="pill ${kind||(/green|ready|delivered|received|closed/.test(text)?'green':/red|locked|discrepancy|conflict|cancelled/.test(text)?'red':'amber')}">${esc(pretty(text))}</span>`;
  const btn=(label,action,id='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
  const options=(items,current)=>items.map(x=>{const value=typeof x==='string'?x:x.value,label=typeof x==='string'?x:x.label;return `<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`;}).join('');
  const input=(label,name,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
  const select=(label,name,items,current)=>`<label>${label}<select name="${name}">${options(items,current)}</select></label>`;
  const note=(label,name,value='')=>`<label>${label}<textarea name="${name}" rows="3">${esc(value)}</textarea></label>`;
  const errorBox=()=>'<p class="form-error" role="alert"></p>';
  let actorKey='admin', path='dispatch', selected=null, drafts=new Map(), rows=[], parsing=false, cancelParsing=false, busy=false, pending=null,timer=null;
  const amountDrafts=new Map();
  function restoreDrafts(){try{const saved=JSON.parse(window.sessionStorage?.getItem('lannpya.form-drafts.v4')||'null');if(saved&&Date.now()-saved.at<1800000){drafts=new Map(saved.customer||[]);for(const [id,d]of saved.amounts||[])amountDrafts.set(id,d);}}catch{/* drafts are optional */}}
  function stashDrafts(){try{window.sessionStorage?.setItem('lannpya.form-drafts.v4',JSON.stringify({at:Date.now(),customer:[...drafts],amounts:[...amountDrafts]}));}catch{/* retain memory draft */}}
  restoreDrafts();
  let scenario='normal', localOffline=false, filter={search:'',triage:'',state:'',rider:'',date:'',readiness:''};
  const actor=()=>W.ACTORS[actorKey];
  const localTime=()=>new Date(store.now()+23400000).toISOString().slice(0,16);
  const offline=()=>localOffline||!navigator.onLine;
  const ownOrders=()=>store.snapshot().orders;
  const tokenFor=o=>o.link?.token||'';
  const customerURL=token=>`${location.href.split('#')[0]}#/track/${encodeURIComponent(token)}`;
  function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3500);}
  function failure(err,form){const target=form?.querySelector('.form-error');if(target)target.textContent=err.message;else toast(err.message);}
  function cmd(type,p={},meta={}){if(scenario==='save_failure')throw Error('Simulated save failure. Your form is retained; select Normal to retry.');return store.execute(type,p,actor(),meta);}
  async function submit(type,p,form,meta={}){if(busy)return;busy=true;try{if(scenario==='slow')await new Promise(r=>setTimeout(r,750));const result=cmd(type,p,meta);render();toast(result.pending?'Action queued locally — not acknowledged by a server.':'Saved in the local demo workspace.');return result;}catch(err){failure(err,form);}finally{busy=false;}}
  function go(route){location.hash='#/'+route;}
  function toolbar(){return `<div class="prototype-bar"><strong>Functional prototype</strong><span>${store.snapshot().clockMode==='fixed'?'Test clock':'Live clock'} · ${esc(localTime().replace('T',' '))} Yangon</span><a href="#/dispatch">Admin</a><a href="#/customer">Customer</a><a href="#/ride">Rider</a><a href="#/scenarios">Test scenarios</a><a href="http://127.0.0.1:8000/api.html">API workspace</a></div>`;}
  function nav(){return `<aside class="sidebar"><div class="brand"><div class="brand-mark">L</div><div><strong>LannPya</strong><span>delivery control</span></div></div><nav class="nav">${[['dispatch','Order board'],['manual','＋ Add order'],['new','Paste orders'],['routes','Routes / departure'],['buyers','Customer links'],['exceptions','Exceptions'],['closeout','Hub closeout'],['analytics','Operational counts'],['settings','Hub policy'],['scenarios','Test scenarios']].map(([v,label])=>`<a class="nav-item ${path===v?'active':''}" href="#/${v}">${label}</a>`).join('')}</nav><div class="sidebar-footer">Device-local demo<br>No live courier connection</div></aside>`;}
  function render(){
    store.refresh();path=location.hash.replace(/^#\/?/,'')||'dispatch';
    const customer=path==='customer'||path.startsWith('track/'), rider=path==='ride'||path.startsWith('ride/');
    if(customer)actorKey='customer';else if(rider){if(actor().role!=='rider')actorKey='rider';}else actorKey='admin';
    document.body.classList.toggle('experience',customer||rider);
    document.body.classList.add('local-workspace');
    document.body.classList.toggle('role-customer',customer);
    document.body.classList.toggle('role-rider',rider);
    document.body.classList.toggle('role-admin',!customer&&!rider);
    if(!rider)document.body.classList.remove('night');
    let body;
    try{body=customer?(path==='customer'?customerHome():customerView(decodeURIComponent(path.slice(6)))):rider?riderView():adminView();}catch(err){body=`<div class="panel functional-card"><h1>Unable to open this view</h1><p>${esc(err.message)}</p><a href="#/dispatch">Return to workspace</a></div>`;}
    root.innerHTML=`${toolbar()}<div class="app-shell">${customer||rider?'':nav()}<main class="main"><section class="content ${customer||rider?'experience-content':''}">${body}<p class="local-status">${offline()?'Offline / simulated offline':'Browser online'} · ${store.persistent()?'Saved on this device':'Memory only — persistent storage unavailable'} · ${store.snapshot().outbox.filter(x=>x.status!=='acknowledged').length} pending/conflicted local actions. No server sync.</p></section></main></div>`;
    wire();
    wirePresentation();
    if(customer&&path!=='customer')wireCustomer(decodeURIComponent(path.slice(6)));
    if(rider)wireRider();
    if(path==='dispatch')wireFilters();
  }
  const heading=(title,sub,actions='')=>`<div class="page-head"><div><div class="kicker">LANNPYA · LOCAL FUNCTIONAL WORKSPACE</div><h1>${title}</h1><p class="subhead">${sub}</p></div><div class="head-actions">${actions}</div></div>`;
  // Presentation helpers only: the workflow store and action handlers are unchanged.
  function wirePresentation(){document.querySelectorAll('a[data-local-section]').forEach(link=>link.onclick=e=>{e.preventDefault();document.querySelector('#'+link.dataset.localSection)?.scrollIntoView?.({behavior:'smooth',block:'start'});});}
  function localOverview(){const st=store.snapshot();return `<section class="dashboard-balance local-overview"><div><span>Your delivery workspace</span><strong>${st.orders.length}</strong><small>${st.orders.filter(o=>o.state==='delivered').length} delivered · ${st.orders.filter(o=>o.state==='held').length} awaiting review</small></div></section><nav class="quick-actions" aria-label="Delivery shortcuts"><a href="#/manual"><span class="shortcut-glyph">＋</span><span>Add order</span></a><a href="#/new"><span class="shortcut-glyph">▤</span><span>Paste orders</span></a><a href="#/routes"><span class="shortcut-glyph">↱</span><span>Plan a route</span></a><a href="#/closeout"><span class="shortcut-glyph">⇄</span><span>Hub closeout</span></a></nav>`;}
  function customerHeading(state){return state==='delivered'?'Your parcel has arrived.':state==='out_for_delivery'?'On the way to your doorstep.':state==='cancelled'?'Delivery cancelled.':['returned','return_pending'].includes(state)?'Your delivery update.':'Your delivery, made simple.';}
  function localTracking(state){const step=state==='delivered'?3:state==='out_for_delivery'?2:state==='assigned'?1:0;return `<div class="delivery-track-card"><ol class="delivery-progress" aria-label="Delivery progress">${['Order received','Ready','Out for delivery','Delivered'].map((text,i)=>`<li class="${i<=step?'is-reached':''} ${i===step?'is-current':''}" ${i===step?'aria-current="step"':''}><span class="progress-node"></span><span>${text}</span></li>`).join('')}</ol><p class="track-caption">Current delivery status<strong>${esc(pretty(state))}</strong></p></div>`;}
  function localRiderMap(o){return `<section class="route-map local-route-map" aria-label="Illustrative route overview, not live navigation"><div class="map-grid" aria-hidden="true"><div class="map-river"></div><div class="map-park park-one"></div><div class="map-park park-two"></div><svg class="map-streets" viewBox="0 0 480 300" preserveAspectRatio="none"><path d="M-20 250 510 30M-20 40 490 235M90-20 160 330M300-20 340 330M-20 160 510 155" stroke="#fff" stroke-width="12" fill="none"/><path d="M140 238v-48l44-21h67l24-36h75" stroke="#fff" stroke-width="9" fill="none"/><path d="M140 238v-48l44-21h67l24-36h75" stroke="#203448" stroke-width="5" fill="none"/><circle cx="140" cy="238" r="8" fill="#2053df" stroke="white" stroke-width="4"/><circle cx="350" cy="133" r="7" fill="#203448" stroke="white" stroke-width="3"/></svg></div><span class="map-town">${esc(W.PLACES.find(p=>p.id===o.areaId)?.name||'Yangon')}</span><div class="map-destination"><div><strong>${esc(o.street||o.name)}</strong><span>Schematic overview · not live GPS</span></div></div><span class="map-disclaimer">Illustrative layout · use Google Maps for navigation</span></section>`;}
  function manualView(){return heading('Add an order','Enter the parcel directly. Customer link is created automatically. No chat parsing required.')+`<div class="panel functional-card"><form id="manual-form"><div class="form-grid">${input('Recipient name','name','','text','required')}${input('Recipient phone','phone','','tel','required')}${input('Sender / business name (optional)','sender','','text')}${input('Parcel / item description','item','','text','required')}${input('Invoice / reference (optional)','reference')}${select('Township','areaId',W.PLACES.filter(a=>store.snapshot().policy.areas.includes(a.id)).map(a=>({value:a.id,label:a.name})),store.snapshot().policy.areas[0])}${input('Street / address','street')}${input('Landmark','landmark')}${input('Floor / unit','floor')}${select('Payment','payment',['cod','prepaid'],'cod')}${input('COD amount in MMK (zero for prepaid)','expected','','number','min="0" step="1" required')}${input('Delivery day','date',W.day(store.now()),'date','required')}${select('Availability','time',[W.ANY_TIME,...W.WINDOWS],W.ANY_TIME)}</div>${note('Delivery instructions (maximum 300 characters)','note')}<details><summary>Known location coordinates (optional)</summary><p>Leave both blank to let the customer submit a location for admin review. Fixture Kamayut reference: 16.8254, 96.1309; Sanchaung: 16.8034, 96.132. These are preview points, not verified addresses.</p><div class="form-grid">${input('Latitude','lat','','number','step="any"')}${input('Longitude','lng','','number','step="any"')}</div><label class="inline-check"><input type="checkbox" name="locationReviewed"> I have verified these coordinates for this delivery</label></details><label class="inline-check"><input type="checkbox" name="received"> The parcel has physically arrived at the hub</label><label class="inline-check"><input type="checkbox" name="createSeparate"> Intentionally create a separate parcel if this reference already exists</label><button class="btn green">Create order and customer link</button>${errorBox()}</form></div>`;}
  function customerHome(){const entries=store.snapshot().orders.filter(o=>o.link&&store.linkStatus(o.id)==='active');return `<div class="customer-wrap">${heading('Customer delivery','Open the confirmation link supplied by your delivery admin.')}<div class="customer-card"><form id="customer-link-form">${input('Delivery link or token','link','','text','required placeholder="Paste your confirmation link"')}<button class="customer-primary">Open my delivery</button>${errorBox()}</form></div><div class="panel functional-card"><h2>Local customer preview</h2><p>This list is for testing on this device. Live customers will receive only their own private delivery link.</p>${entries.length?entries.map(o=>`<div class="exception-row"><strong>${esc(o.id)} · ${esc(o.item)}</strong><p>${pretty(o.state)}</p><a class="btn green" href="#/track/${encodeURIComponent(o.link.token)}">Open this delivery</a></div>`).join(''):'<p>No active customer links yet. Admin must add an order first.</p><a class="btn" href="#/manual">Admin: add the first order</a>'}</div></div>`;}
  function initialLocationForm(o,d,token){const area=W.PLACES.find(a=>a.id===o.areaId);return `<form id="customer-form" data-version="${d.version}">${o.confirmation?'<div class="customer-notice"><strong>Your preferences were saved. Your location is awaiting admin approval.</strong></div>':''}<div class="action-row">${btn('Reload latest details (discard unsaved changes)','refresh-customer',token)}</div><h2>Where should we deliver?</h2><p>No verified pin exists yet. Submit a location and your availability. The admin will review your point before dispatch.</p><div class="form-grid">${input('Latitude','latitude',d.pin?.lat??o.proposedPin?.lat??'','number','step="any" required')}${input('Longitude','longitude',d.pin?.lng??o.proposedPin?.lng??'','number','step="any" required')}</div><div class="action-row">${btn('Use my current location','get-location')}${btn('Use township preview point (test only)','preview-location',area?.id||'')}</div><p class="sheet-copy">The preview point is approximate and always requires admin approval. If GPS is unavailable, enter your coordinates or ask the admin for help.</p>${select('How will you receive it?','answer',['At home','Reschedule','Leave with security'],d.answer)}${select('Availability','time',[W.ANY_TIME,...W.WINDOWS].filter(t=>o.date>W.day(store.now())||o.date===W.day(store.now())&&W.endMinute(t)>W.minute(store.now())),d.time)}<label class="inline-check"><input type="checkbox" name="securityPays" ${d.securityPays?'checked':''}> If leaving a COD parcel with security, they can pay the amount due</label><label>Note to rider<textarea name="note" maxlength="300" rows="3">${esc(d.note)}</textarea></label><button class="customer-primary">Submit location and delivery preferences</button>${errorBox()}</form>`;}
  function adminView(){
    if(actor().role==='rider'&&!['scenarios'].includes(path))return `<div class="panel functional-card"><h1>Dispatcher access required</h1><p>The selected rider can access assigned route work.</p><a href="#/ride">Open rider workspace</a></div>`;
    if(path==='manual')return manualView();
    if(path==='new')return intakeView();
    if(path.startsWith('order/'))return detailView(path.slice(6));
    return ({dispatch:boardView,routes:routesView,buyers:linksView,exceptions:exceptionsView,closeout:closeoutView,settings:settingsView,analytics:metricsView,scenarios:scenariosView}[path]||boardView)();
  }
  function metricsView(){const os=ownOrders(),attempted=os.filter(o=>o.attempts.length),first=attempted.filter(o=>o.attempts[0]?.outcome==='delivered');return heading('Operational counts','Derived from current local records. Only orders you create are counted.')+`<div class="metrics">${[['Parcels',os.length],['Held',os.filter(o=>o.state==='held').length],['Delivered',os.filter(o=>o.state==='delivered').length],['First-attempt delivery',attempted.length?`${first.length}/${attempted.length}`:'No attempts']].map(([label,value])=>`<div class="metric"><div class="metric-top">${label}</div><div class="metric-value">${value}</div></div>`).join('')}</div><p>Cancelled and unattempted parcels are excluded from the first-attempt denominator. Historical migrated records without attempt history are excluded. No estimated ROI, live ETA or measured pilot result is claimed.</p>`;}
  function boardView(){return localOverview()+heading('Admin order board','Intake → review → receive → assign → depart.',`<a class="btn primary" href="#/manual">＋ Add order</a><a class="btn" href="#/new">Paste orders</a>`)+`${store.snapshot().resetNotice?`<p class="notice">${esc(store.snapshot().resetNotice)}</p>`:''}<div class="filter-grid"><label>Search<input id="search" value="${esc(filter.search)}" placeholder="ID, name, phone or invoice"></label><label>Triage<select id="triage-filter">${options(['','green','amber','red'],filter.triage)}</select></label><label>Lifecycle<select id="state-filter">${options(['','held','ready','assigned','out_for_delivery','retry_pending','return_pending','returned','delivered','cancelled'],filter.state)}</select></label><label>Rider<select id="rider-filter">${options([{value:'',label:'All riders'},...Object.values(W.ACTORS).filter(a=>a.role==='rider').map(a=>({value:a.id,label:a.name}))],filter.rider)}</select></label><label>Delivery day<input id="date-filter" type="date" value="${filter.date}"></label><label>Readiness<select id="ready-filter">${options([{value:'',label:'All'},{value:'blocked',label:'Has blockers'},{value:'eligible',label:'No blockers'}],filter.readiness)}</select></label></div><div id="board-results">${boardRows()}</div>`;}
  function boardRows(){const st=store.snapshot(),os=ownOrders().filter(o=>{const t=store.triage(o.id).level,r=st.routes.find(r=>r.id===o.routeId);return (!filter.search||[o.id,o.name,o.phone,o.reference].join(' ').toLowerCase().includes(filter.search.toLowerCase()))&&(!filter.triage||t===filter.triage)&&(!filter.state||o.state===filter.state)&&(!filter.date||o.date===filter.date)&&(!filter.rider||r?.riderId===filter.rider)&&(!filter.readiness||(store.blockers(o.id).length>0)===(filter.readiness==='blocked'));});return `<p>${os.length} matching orders · ${st.orders.length} workspace records</p><div class="panel table-scroll"><table class="data-table"><thead><tr><th>Order / recipient</th><th>Address quality</th><th>Parcel status</th><th>Amount / window</th><th>Next action</th></tr></thead><tbody>${os.map(o=>`<tr><td><a href="#/order/${o.id}"><strong>${o.id}</strong> · ${esc(o.name||'Name not extracted')}</a><small>${esc(o.reference||o.item)}</small></td><td>${pill(store.triage(o.id).level)}<small>${esc(store.triage(o.id).reasons.join('; '))}</small></td><td>${pill(o.state)}</td><td>${amount(o.expected)}<small>${o.date} · ${o.time}</small></td><td>${esc(store.blockers(o.id).join('; ')||'Open to assign / review route')}<br><a href="#/order/${o.id}">Review →</a></td></tr>`).join('')||'<tr><td colspan="5">No matching records. Clear filters or paste orders.</td></tr>'}</tbody></table></div>`;}
  function wireFilters(){for(const [id,key] of [['search','search'],['triage-filter','triage'],['state-filter','state'],['rider-filter','rider'],['date-filter','date'],['ready-filter','readiness']])$('#'+id).oninput=e=>{filter[key]=e.target.value;$('#board-results').innerHTML=boardRows();};}
  function intakeView(){return heading('Paste chat orders','Separate parcels with a line containing --- or a blank line. Review every boundary before creating orders.')+`<div class="panel functional-card"><div class="action-row">${btn('Load Burmese sample set','sample')}${btn('Parse / preview','parse','','primary')}${btn('Cancel unstarted rows','cancel-parse')}</div><label>Original chat batch<textarea id="batch-raw" rows="10" placeholder="Name: …&#10;Phone: 09…&#10;Township: …&#10;COD: …">${esc(window.batchRaw||'')}</textarea></label><p class="sheet-copy">Rules/dictionary extraction only. Encoding requiring conversion is held for manual Unicode review. No names or phone numbers are sent to an AI provider.</p><div id="parse-results">${previewRows()}</div></div>`;}
  function previewRows(){return `<p>${rows.length} boundary records · ${rows.filter(r=>r.status==='parsed').length} parsed · ${rows.filter(r=>r.status==='failed').length} failed ${parsing?'· Processing…':''}</p>${rows.map((r,i)=>`<div class="preview-row"><div class="action-row"><strong>Record ${i+1}</strong>${pill(r.status)}${r.status==='failed'||r.status==='cancelled'?btn('Retry this record','retry-row',String(i)):''}</div><textarea data-row-raw="${i}" rows="4">${esc(r.raw)}</textarea>${r.error?`<p role="alert">${esc(r.error)}</p>`:''}${r.fields?`<p>${esc(r.fields.name||'Name unresolved')} · ${esc(r.fields.phone||'Phone unresolved')} · ${esc(r.fields.areaId||'Area unresolved')} · ${amount(r.fields.expected)}</p>${pill(W.triage(r.fields).level)}<p>${esc(r.fields.warnings.join(' '))}</p>${r.duplicates.length?`<p class="notice">Likely duplicate: ${esc(r.duplicates.map(o=>o.id).join(', '))}</p>`:''}<label>Import choice<select data-choice="${i}">${options([{value:'include',label:r.duplicates.length?'Review duplicate choice':'Include order'},{value:'skip',label:'Skip this record'},...(r.duplicates.length?[{value:'separate',label:'Create separately (intentional duplicate)'}]:[])],r.choice)}</select></label>`:''}</div>`).join('')}${rows.length?btn('Create selected parsed records','commit-batch','','green'):''}`;}
  async function parseBatch(single){if(parsing)return;const raw=$('#batch-raw')?.value||window.batchRaw||'';window.batchRaw=raw;if(single==null){rows=raw.split(/\r?\n\s*---\s*\r?\n|\r?\n\s*\r?\n/).map(s=>s.trim()).filter(Boolean).map(raw=>({raw,status:'waiting',choice:'include'}));if(!rows.length)return toast('Paste at least one order.');}parsing=true;cancelParsing=false;const targets=single==null?rows.map((_,i)=>i):[single];for(const i of targets){if(cancelParsing){rows[i].status='cancelled';continue;}rows[i].status='processing';paintPreview();await new Promise(r=>setTimeout(r,scenario==='slow'?650:80));try{if(scenario==='parse_failure'&&i===targets[0])throw Error('Simulated parser error — retry this record in Normal mode.');rows[i].fields=W.parse(rows[i].raw);rows[i].duplicates=store.duplicate(rows[i].fields);rows[i].status='parsed';delete rows[i].error;}catch(err){rows[i].status='failed';rows[i].error=err.message;}paintPreview();}parsing=false;paintPreview();}
  function paintPreview(){if($('#parse-results')){$('#parse-results').innerHTML=previewRows();wireActions($('#parse-results'));}}
  function detailView(id){const o=store.order(id,actor()),t=store.triage(id),frozen=!store.canEdit(id),area=W.PLACES.find(p=>p.id===o.areaId);return heading(`${esc(o.id)} · ${esc(o.name||'Unresolved recipient')}`,`${pretty(o.state)} · ${o.date} · Record version ${o.version}`)+`<div class="detail-grid"><div class="panel functional-card"><h2>Review order fields ${pill(t.level)}</h2><p>${esc(t.reasons.join('; '))}</p>${frozen?'<p class="notice">Fields frozen after departure/completion. Use operational exceptions instead.</p>':''}<form id="edit-form" data-id="${o.id}" data-version="${o.version}"><fieldset ${frozen?'disabled':''}><div class="form-grid">${input('Recipient','name',o.name)}${input('Sender','sender',o.sender||'LannPya Delivery')}${input('Phone','phone',o.phone)}${select('Supported demo township','areaId',[{value:'',label:'Unknown'},...W.PLACES.map(p=>({value:p.id,label:p.name}))],o.areaId)}${input('Street','street',o.street)}${input('Landmark','landmark',o.landmark)}${input('Floor / unit','floor',o.floor)}${input('Item','item',o.item)}${input('Invoice reference','reference',o.reference)}${select('Payment mode','payment',['unknown','cod','prepaid'],o.payment)}${input('Expected MMK','expected',o.expected??'','number','min="0" step="1"')}${input('Delivery day','date',o.date,'date','required')}${select('Window','time',[W.ANY_TIME,...W.WINDOWS],o.time)}</div>${note('Instructions','note',o.note)}${note('Normalized Unicode text (manual conversion if needed)','normalized',o.normalized)}<label class="inline-check"><input type="checkbox" name="unicodeReviewed" ${!o.encodingReview?'checked':''}> I reviewed the encoding / Unicode text</label>${input('Correction reason','reason','','text','required')}<button class="btn primary">Save fields and rerun checks</button></fieldset>${errorBox()}</form><details><summary>Original chat — vague phrases highlighted</summary><pre>${esc(o.raw).replace(/near|နား|အနီး/gi,m=>`<mark>${m}</mark>`)}</pre></details><details><summary>Field sources</summary><table class="data-table">${Object.entries(o.provenance||{}).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v.source)}</td><td>${esc(v.evidence)}</td></tr>`).join('')}</table></details></div><div class="right-stack"><div class="panel functional-card"><h2>Readiness and custody</h2><ul>${store.blockers(id).map(b=>`<li>${esc(b)}</li>`).join('')||'<li>No readiness blockers</li>'}</ul><p>At hub: ${o.received?'Received':'Not recorded'}<br>Location: ${esc(pretty(o.location))}<br>Route: ${esc(o.routeId||'Unassigned')}</p><div class="action-row">${o.proposedPin?btn('Review customer location','approve-location',id):''}${!frozen?btn('Verify original location','location',id):''}${!o.received&&!frozen&&actor().role==='admin'?btn('Parcel physically received','receive',id):''}${actor().role==='admin'&&!o.routeId&&!frozen?btn('Assign rider / route','assign',id):''}${o.routeId&&!frozen&&actor().role==='admin'?btn('Unassign draft stop','unassign',id):''}${!['delivered','returned','cancelled'].includes(o.state)?btn('Cancel / request return','cancel',id):''}</div></div><div class="panel functional-card"><h2>Customer link</h2><p>${pill(store.linkStatus(id))} ${o.link?.shared?'· Marked manually shared':''}</p>${o.link?`<p>Expiry: ${esc(new Date(o.link.expires).toLocaleString('en-GB',{timeZone:'Asia/Rangoon'}))}</p>`:''}<div class="action-row">${!frozen?btn(o.link?'Reissue link (revokes old)':'Create link','issue',id):''}${o.link?btn('Copy link','copy',id)+btn('Mark manually shared','shared',id)+btn('Revoke link','revoke',id):''}</div>${o.link?`<a href="#/track/${encodeURIComponent(o.link.token)}">Open customer preview →</a>`:''}<p class="sheet-copy">Copying does not send a Messenger message. Admin shares the link in its own chat.</p></div><div class="panel functional-card"><h2>Result / exceptions</h2><p>${o.confirmation?esc(`${o.confirmation.answer} · ${o.confirmation.time}`):'No buyer confirmation'}</p>${o.collection?`<p>Expected ${amount(o.collection.expected)}<br>Recorded ${amount(o.collection.actual)}</p>${o.collection.discrepancy?pill(o.collection.resolution?'resolved discrepancy':'discrepancy'):''}`:''}<p>${o.incident?esc(o.incident):'No incident recorded'}</p><div class="action-row">${actor().role==='admin'?btn(o.incident?'Resolve incident':'Record parcel incident','incident',id):''}${o.collection?.discrepancy&&!o.collection.resolution&&actor().role==='admin'?btn('Resolve cash discrepancy','discrepancy',id):''}${o.state==='return_pending'&&actor().role==='admin'?btn('Hub physically received return','return-received',id):''}${o.state==='returned'&&actor().role==='admin'?btn('Plan new delivery cycle','replan',id):''}</div></div><details class="panel functional-card"><summary>Attempt and audit history</summary>${o.attempts.map(a=>`<p>${esc(a.outcome)} · ${esc(a.reason)} · ${a.riderId}</p>`).join('')||'<p>No delivery attempts.</p>'}${store.snapshot().events.filter(e=>e.orderId===id).map(e=>`<p>${esc(pretty(e.type))}: ${esc(e.text)}<small>${esc(e.actor)}</small></p>`).join('')}</details></div></div><p>Fixture geography: ${esc(area?.name||'No matched area')}. Location review uses approximate demo boundaries.</p>`;}
  function linksView(){return heading('Customer links','Link access, delivery response and parcel status are tracked separately.')+`<div class="panel table-scroll"><table class="data-table"><tr><th>Order</th><th>Link</th><th>Buyer response</th><th>Action</th></tr>${ownOrders().map(o=>`<tr><td><a href="#/order/${o.id}">${o.id}</a><small>${esc(o.name)}</small></td><td>${pill(store.linkStatus(o.id))}</td><td>${esc(o.confirmation?`${o.confirmation.answer} · ${o.confirmation.time}`:'Pending')}</td><td>${btn(o.link?'Reissue':'Create','issue',o.id)}${o.link?btn('Copy','copy',o.id):''}</td></tr>`).join('')}</table></div>`;}
  function routesView(){const st=store.snapshot();return heading('Rider routes','Receive and resolve parcels, assign a draft route, then dispatch.',btn('Create route','new-route','','primary'))+st.routes.map(r=>`<div class="panel functional-card"><div class="action-row"><h2>${r.id}</h2>${pill(r.state)}<span>${Object.values(W.ACTORS).find(a=>a.id===r.riderId)?.name||r.riderId} · ${r.date}</span>${r.state==='draft'?btn('Dispatch ready route','dispatch-route',r.id,'green'):''}</div><ol>${r.orderIds.map(id=>store.order(id)).sort((a,b)=>W.startMinute(a.time)-W.startMinute(b.time)).map(o=>`<li><a href="#/order/${o.id}">${esc(o.name||o.id)}</a> · ${o.time} · ${pretty(o.state)} ${store.blockers(o.id).length?`— ${esc(store.blockers(o.id).join('; '))}`:''}</li>`).join('')||'<li>No parcels assigned. Open an eligible order to assign it.</li>'}</ol><p>Active stop: ${r.active||'None'} · ${r.orderIds.length} assigned parcel(s)</p></div>`).join('');}
  function exceptionsView(){const st=store.snapshot(),os=st.orders.filter(o=>o.state==='held'||['return_pending','retry_pending'].includes(o.state)||o.incident||o.collection?.discrepancy&&!o.collection.resolution||['locked','expired'].includes(store.linkStatus(o.id)));return heading('Operational exceptions','Each row has an order owner and an explicit recovery action.')+`<div class="panel functional-card">${os.map(o=>`<div class="exception-row"><a href="#/order/${o.id}"><strong>${o.id} · ${esc(o.name)}</strong></a><p>${esc([...store.blockers(o.id),o.state==='return_pending'?'Hub must receive physical return':'',o.state==='retry_pending'?'Retry scheduled — rider owns next attempt':'',o.collection?.discrepancy&&!o.collection.resolution?'Hub review: cash discrepancy':'',['locked','expired'].includes(store.linkStatus(o.id))?'Admin review: buyer link '+store.linkStatus(o.id):''].filter(Boolean).join('; '))}</p></div>`).join('')||'<p>No parcel exceptions.</p>'}</div><h2>Offline action review</h2>${outboxView()}<p>Lockout is an in-app admin exception, not a sent SMS notification.</p>`;}
  function outboxView(){return `<div class="panel functional-card">${store.snapshot().outbox.map(q=>`<div class="exception-row"><strong>${q.payload.id}</strong> ${pill(q.status)}<p>${esc(q.type)} · Observed by ${esc(q.actor.name)}<br>${esc(q.error||q.resolution||'Awaiting local replay')}</p>${q.status!=='acknowledged'&&actor().role==='admin'?btn('Review observed action','resolve-outbox',q.operationId):''}</div>`).join('')||'<p>No queued actions.</p>'}<div class="action-row">${btn('Replay pending actions locally','replay')}</div><p class="sheet-copy">Replay runs against the local domain, not a connected backend. Conflicts preserve the original rider payload.</p></div>`;}
  function routeCloseout(r,riderMode=false){
    const st=store.snapshot(),os=r.orderIds.map(id=>st.orders.find(o=>o.id===id)),cash=os.reduce((sum,o)=>sum+(o.collection?.actual||0),0);
    const ready=['dispatched','in_progress','closing'].includes(r.state)&&os.every(o=>['delivered','returned'].includes(o.state)),issues=r.state==='closing'?store.closeoutBlockers(r.id):[];
    const riderActions=riderMode&&ready&&r.handover?.status!=='received'?(r.handover?btn('Update handover amount','different-cash',r.id):btn(`Hand over ${amount(cash)}`,'submit-cash',r.id,'green')+btn('Different amount','different-cash',r.id)):'';
    const adminActions=!riderMode&&r.handover&&r.state!=='closed'?(r.handover.status!=='received'?btn('Receive cash & close route','receive-cash',r.id,'green'):issues.length?'':btn('Close route','close-route',r.id,'green')):'';
    return `<div class="panel functional-card"><h2>${r.id} ${pill(r.state)}</h2><p>Recorded cash ${amount(cash)} · ${os.filter(o=>o.state==='delivered').length} delivered · ${os.filter(o=>o.state==='return_pending').length} returns awaiting receipt</p>${os.filter(o=>o.state==='return_pending').map(o=>`<p>${o.id} · ${esc(o.name)} ${!riderMode?btn('Receive physical return','return-received',o.id):'— take parcel back to hub'}</p>`).join('')}<p>Handover: ${esc(r.handover?.status||'not submitted')}${r.handover?` · Rider declared ${amount(r.handover.declared)}${r.handover.received!=null?` · Hub received ${amount(r.handover.received)}`:''}`:''}</p>${riderMode&&ready&&!r.handover?'<p>Tap only when handing this amount to the hub. Use Different amount if your count does not match.</p>':''}${riderMode&&r.handover?.status==='submitted'?'<p>Handover submitted — waiting for the hub to count and receive it.</p>':''}${!riderMode&&issues.length?`<p class="notice">Still open: ${issues.map(esc).join('; ')}.</p>`:''}<div class="action-row">${riderActions}${adminActions}</div></div>`;
  }
  function closeoutView(){return heading('Hub closeout','Count the cash and confirm receipt once. The route closes automatically when parcels, returns and differences are accounted for.')+store.snapshot().routes.map(r=>routeCloseout(r)).join('');}
  function settingsView(){const p=store.snapshot().policy;return heading('Hub policy','Versioned working defaults; applies to the local simulation.')+`<div class="panel functional-card"><p>Policy version ${p.version} · Asia/Rangoon · fixed 500 m radius · one demo hub</p><form id="policy-form"><label class="inline-check"><input type="checkbox" name="enforceCutoff" ${p.enforceCutoff?'checked':''}> Enforce a daily customer edit cutoff (otherwise edits close at dispatch)</label>${input('Self-service cutoff (hub local time)','cutoff',`${String(Math.floor(p.cutoff/60)).padStart(2,'0')}:${String(p.cutoff%60).padStart(2,'0')}`,'time','required')}<fieldset><legend>Enabled fixture townships</legend>${W.PLACES.map(a=>`<label class="inline-check"><input type="checkbox" name="area-${a.id}" ${(p.areas||W.PLACES.map(p=>p.id)).includes(a.id)?'checked':''}>${a.name}</label>`).join('')}</fieldset>${input('Allowed same-day retries after first attempt','maxRetries',p.maxRetries,'number','min="0" max="3" required')}${input('Undelivered link lifetime in days','linkDays',p.linkDays,'number','min="1" max="30" required')}<p>Window choices: ${W.WINDOWS.join(', ')}. Real boundary coverage and retention must be agreed with the pilot hub.</p><button class="btn primary">Save new policy version</button>${errorBox()}</form><details><summary>Policy history</summary><pre>${esc(JSON.stringify(store.snapshot().policyHistory,null,2))}</pre></details></div>`;}
  function scenariosView(){return heading('Functional test controls','These controls live outside the customer/rider product flows and only simulate local behavior.')+`<div class="panel functional-card"><label>Interaction mode<select id="scenario">${options([{value:'normal',label:'Normal'},{value:'slow',label:'Slow parser/save'},{value:'parse_failure',label:'Parser record failure'},{value:'save_failure',label:'Fail writes (retain form)'},{value:'no_map',label:'Map unavailable'},{value:'no_gps',label:'GPS denied — manual location still available'},{value:'no_voice',label:'Voice unavailable'}],scenario)}</select></label><label class="inline-check"><input type="checkbox" id="offline-mode" ${localOffline?'checked':''}> Simulate offline rider queue</label><form id="clock-form">${input('Demo operating clock (Yangon time)','clock',localTime(),'datetime-local','required')}<button class="btn">Set demo clock</button>${errorBox()}</form><p>New orders use the real clock by default. Manual orders offer Any time for immediate testing. Setting a demo clock freezes time until you select Use real date/time.</p><div class="action-row">${btn('Use real date/time','live-clock')}${btn('Export workspace backup','export')}${btn('Simulate stale offline version','stale')}</div><h3>Dependency boundaries</h3><p>Small fixture place dictionary; manual Unicode review; no external AI; schematic pin; preview actors, not sign-in. Offline actions can be replayed locally but do not sync to another device.</p></div>${outboxView()}<div class="panel functional-card"><h2>Review journeys</h2><ol><li>Paste samples → review blocked fields → verify location/payment → receive parcel → assign.</li><li>Issue customer link → verify last four demo digits → choose future time → confirm.</li><li>Dispatch route → set clock to delivery window → acknowledge route → active stop → deliver/undo/COD.</li><li>Record failure → eligible retry or request return → hub receives parcel.</li><li>Resolve collection discrepancy → submit rider cash → hub receipt → close route.</li><li>Queue offline → change a record version → replay → review conflict with reason.</li></ol></div>`;}
  function customerView(token){const c=store.customer(token);if(!c.available)return `<div class="customer-card customer-wrap"><h1>${c.status==='locked'?'This link is locked':'Delivery link unavailable'}</h1><p>${esc(pretty(c.status))}. Contact the delivery admin for a new link or help.</p></div>`;const o=c.order;return `<div class="customer-wrap"><div class="customer-top"><div class="brand"><div class="brand-mark">L</div><div><strong>LannPya</strong><span>လမ်းပြ · your delivery</span></div></div>${pill(c.state)}</div><div class="customer-card"><div class="customer-admin"><div class="avatar peach">LP</div><div><strong>${esc(c.sender)}</strong><span>Invoice ${esc(c.reference||c.id)}</span></div></div><div class="customer-title"><div class="product" aria-hidden="true">✿</div><h1>${customerHeading(c.state)}</h1><p class="customer-parcel-name">${esc(c.item)}</p><p>${c.payment==='prepaid'?'Prepaid — no cash to collect':c.payment==='cod'?`${amount(c.expected)} due on delivery`:'Admin is reviewing the payment amount.'}</p><p>No payment, password or app install requested.</p></div>${localTracking(c.state)}${!c.verified?`<div class="verification"><h2>Confirm your phone digits</h2><form id="verify-form"><label>Last four recipient phone digits<input name="digits" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" required autocomplete="off"></label><p class="demo-hint">Use the last four digits of this order’s recipient phone number. ${c.remaining} tries remaining.</p><button class="customer-primary">Verify and continue</button>${errorBox()}</form></div>`:o.state==='delivered'?`<div class="customer-notice"><div><strong>Your parcel was delivered.</strong><p>${amount(c.collection?.actual||0)} recorded as collected.</p></div></div>`:['returned','return_pending','cancelled'].includes(o.state)?`<h2>${o.state==='return_pending'?'Your parcel is returning to the hub.':o.state==='returned'?'Your parcel is back at the hub.':'Delivery cancelled.'}</h2><p>Contact the delivery admin to arrange the next step.</p>`:customerForm(o,c,token)}<p class="privacy">Your order details are shared with the assigned delivery team.</p></div></div>`;}
  function customerForm(o,c,token){const d=drafts.get(token)||{pin:o.pin?{...o.pin}:o.proposedPin?{...o.proposedPin}:null,time:o.time,answer:o.confirmation?.answer||'At home',note:o.note||'',version:o.version};drafts.set(token,d);if(!c.editable)return `<div class="customer-notice"><div><strong>Delivery details are view-only.</strong><p>The hub cutoff or route departure has passed. Ask the delivery admin about late changes.</p><p>${esc(o.confirmation?.answer||'Pending response')} · ${o.time} · ${esc(o.note||'No rider note')}</p></div></div>`;if(!o.anchor)return initialLocationForm(o,d,token);return `<form id="customer-form" data-version="${d.version}">${o.confirmation?`<div class="customer-notice"><strong>Saved: ${esc(o.confirmation.answer)} · ${o.confirmation.time}</strong></div>`:''}${d.version!==o.version?'<p class="notice">Delivery details changed since this draft started. Review the latest record before saving.</p>':''}<div class="action-row">${btn('Reload latest details (discard unsaved changes)','refresh-customer',token)}</div><h2>1. Check your location</h2><p class="sheet-copy">Schematic demo pin editor — 500 m from the fixed original anchor and inside the original demo township.</p>${scenario==='no_map'?'<p class="notice">Map unavailable. Use the direction controls or retain your existing pin.</p>':''}${scenario==='no_gps'?'<p>GPS permission denied. Manual adjustment remains available.</p>':''}<div class="pin-editor" id="pin-editor"><div class="map-bg"></div><div class="pin-boundary"><span>500 m</span></div><div id="editable-pin" class="editable-pin">⌖</div></div><div class="pin-toolbar">${[['←',-50,0],['↑',0,50],['↓',0,-50],['→',50,0]].map(([label,x,y])=>`<button type="button" data-nudge="${x},${y}" aria-label="Move location ${label} by 50 metres">${label} 50 m</button>`).join('')}<button type="button" id="reset-pin">Reset</button></div><p id="pin-distance" class="sheet-copy" aria-live="polite"></p><h2>2. Delivery preference</h2>${select('How will you receive it?','answer',['At home','Reschedule','Leave with security'],d.answer)}${select('Available future window','time',[W.ANY_TIME,...W.WINDOWS].filter(t=>o.date>W.day(store.now())||o.date===W.day(store.now())&&W.endMinute(t)>W.minute(store.now())),d.time)}<label class="inline-check"><input type="checkbox" name="securityPays" ${d.securityPays?'checked':''}> If leaving a COD parcel with security, they can pay the amount due</label><label>Note to rider (maximum 300 characters)<textarea name="note" maxlength="300" rows="3">${esc(d.note)}</textarea></label><button class="customer-primary">${o.confirmation?'Save delivery changes':'Confirm delivery details'}</button>${errorBox()}</form>`;}
  function wireCustomer(token){const verify=$('#verify-form');if(verify)verify.onsubmit=e=>{e.preventDefault();try{store.verify(token,new FormData(verify).get('digits'));render();}catch(err){if(store.customer(token).status==='locked')render();else{failure(err,verify);verify.querySelector('input').value='';}}};const form=$('#customer-form');if(!form)return;const c=store.customer(token),o=c.order,d=drafts.get(token);const saveDraft=()=>{const data=new FormData(form);Object.assign(d,{answer:data.get('answer'),time:data.get('time'),note:data.get('note'),securityPays:data.has('securityPays')});if(!o.anchor){d.pin=data.get('latitude')!==''&&data.get('longitude')!==''?{lat:Number(data.get('latitude')),lng:Number(data.get('longitude'))}:null;}stashDrafts();};form.oninput=saveDraft;form.onsubmit=async e=>{e.preventDefault();saveDraft();if(busy)return;busy=true;try{if(offline())throw Error('You are offline. Draft retained; reconnect before confirming to the delivery team.');if(scenario==='slow')await new Promise(r=>setTimeout(r,750));if(scenario==='save_failure')throw Error('Simulated save failure. Draft retained.');const result=store.confirm(token,{...d,expectedVersion:d.version});drafts.delete(token);stashDrafts();render();toast(result.order.anchor?'Delivery preferences confirmed.':'Location submitted — awaiting admin approval.');}catch(err){failure(err,form);}finally{busy=false;}};if(!o.anchor)return;
    function move(x,y){const pin={lat:o.anchor.lat+y/111320,lng:o.anchor.lng+x/(111320*Math.cos(o.anchor.lat*Math.PI/180))};const area=W.PLACES.find(a=>a.id===o.areaId);if(W.distance(o.anchor,pin)>500||!area||pin.lat<area.bounds[0]||pin.lat>area.bounds[1]||pin.lng<area.bounds[2]||pin.lng>area.bounds[3])return toast('Keep the pin inside the original 500 m circle and original demo township.');d.pin=pin;stashDrafts();paint();}function offset(){return {x:((d.pin?.lng||o.anchor.lng)-o.anchor.lng)*111320*Math.cos(o.anchor.lat*Math.PI/180),y:((d.pin?.lat||o.anchor.lat)-o.anchor.lat)*111320};}function paint(){const v=offset();$('#editable-pin').style.left=`${50+v.x/500*40}%`;$('#editable-pin').style.top=`${50-v.y/500*40}%`;$('#pin-distance').textContent=`${Math.round(W.distance(o.anchor,d.pin||o.anchor))} m from original location`;}
    $('#pin-editor').onclick=e=>{const b=e.currentTarget.getBoundingClientRect();move((e.clientX-b.left-b.width/2)/(b.width*.4)*500,-(e.clientY-b.top-b.height/2)/(b.height*.4)*500);};document.querySelectorAll('[data-nudge]').forEach(b=>b.onclick=()=>{const [x,y]=b.dataset.nudge.split(',').map(Number),v=offset();move(v.x+x,v.y+y);});$('#reset-pin').onclick=()=>{d.pin={...o.anchor};stashDrafts();paint();};paint();}
  function riderActor(){return actor().role==='rider'?actor():W.ACTORS.rider;}
  function riderView(){const a=riderActor(),st=store.snapshot(),rs=st.routes.filter(r=>r.riderId===a.id),prepared=st.downloads?.[a.id],queue=offline()&&!prepared?[]:store.queue(a);if(!queue.some(o=>o.id===selected))selected=queue[0]?.id;const o=queue.find(o=>o.id===selected),pendingIds=st.outbox.filter(q=>q.status!=='acknowledged').map(q=>q.payload.id);return `<div class="rider-wrap" id="local-ride-top">${o?localRiderMap(o):''}${heading(`Your route, ${esc(a.name)}`,'Stop safely before using your phone.',btn('☾ Theme','theme'))}<label>Preview rider<select id="rider-picker">${options(Object.entries(W.ACTORS).filter(([,a])=>a.role==='rider').map(([value,a])=>({value,label:a.name})),a.id==='rider-2'?'rider2':'rider')}</select></label><div class="action-row">${btn('Prepare assigned queue for offline use','prepare-offline')}</div>${offline()&&!prepared?'<p class="notice">No offline queue was prepared for this rider. Reconnect and prepare assigned work first.</p>':''}${rs.filter(r=>r.state==='dispatched').map(r=>`<div class="notice">${r.id} is dispatched. ${btn('Acknowledge route','ack-route',r.id)}</div>`).join('')}<div class="rider-progress"><div><strong>${offline()&&!prepared?'Queue unavailable offline':queue.length+' remaining stops'}</strong><span>${st.orders.filter(x=>x.state==='delivered'&&rs.some(r=>r.id===x.routeId)).length} delivered on your routes</span></div></div>${o?`<div class="panel next-stop"><div class="action-row">${pill(o.state)}<span>${o.id} · ${o.time} · ${o.date}</span></div><h2>Delivery stop · ${esc(o.name)}</h2>${o.confirmation?`<div class="reply-badge">Buyer confirmed: ${esc(o.confirmation.answer)} · ${o.confirmation.time}</div>`:''}<div class="landmark"><span class="eyebrow">LANDMARK</span><p lang="my">${esc(o.landmark||'Landmark not provided. Review verified street/pin before travel.')}</p><p>${esc(o.street)} · ${esc(o.floor)}</p>${btn('Read landmark aloud','speak',o.id)}${btn('Stop audio','stop-speech')}</div><p>Buyer note: ${esc(o.note||'None')}</p>${scenario==='no_map'?'<p>Navigation unavailable in this scenario. Keep the written street/coordinate below.</p>':`<a class="btn primary maps-link" href="https://www.google.com/maps/dir/?api=1&destination=${o.pin?.lat},${o.pin?.lng}&travelmode=driving" target="_blank" rel="noopener">Open Google Maps</a>`}<p>Verified coordinate: ${o.pin?`${o.pin.lat.toFixed(5)}, ${o.pin.lng.toFixed(5)}`:'Unavailable — ask admin'}</p><p>${o.payment==='prepaid'?'Prepaid — collect no cash':`COD due: ${amount(o.expected)}`}</p><div class="action-row">${btn('Set / keep active stop','active',o.id)}${btn(pending?.id===o.id?'Undo delivery · 2 seconds':'✓ Delivered','delivered',o.id,'green')}${btn('Can’t deliver','failed',o.id)}</div>${pendingIds.includes(o.id)?'<p class="notice">This stop has an unresolved offline action. Review/replay it before recording another result.</p>':''}</div>`:`<div class="panel functional-card"><h2>${offline()&&!prepared?'Offline queue not prepared':'No remaining dispatched stops'}</h2><p>${offline()&&!prepared?'Reconnect to view your assigned stops and prepare offline work. ':''}A draft route is not yet rider work. Ask the admin to receive, assign and dispatch parcels, or review your closeout below.</p></div>`}<div class="panel functional-card"><h2 id="local-ride-queue">Queue</h2>${queue.map(x=>`<button class="rider-queue-row queue-button ${x.id===selected?'selected':''}" data-action="select-stop" data-id="${x.id}"><strong>${esc(x.name)}</strong><span>${x.time} · ${pretty(x.state)} ${x.confirmation?'· Buyer confirmed':''}</span></button>`).join('')||'<p>No current stops.</p>'}${btn('Refresh accepted local changes','refresh-queue')}</div><h2 id="local-ride-handover">History and route handover</h2>${rs.map(r=>routeCloseout(r,true)).join('')}<details class="panel functional-card"><summary>Completed / return history</summary>${st.orders.filter(x=>rs.some(r=>r.id===x.routeId)&&['delivered','returned','return_pending'].includes(x.state)).map(x=>`<p>${x.id} · ${esc(x.name)} · ${pretty(x.state)} · ${amount(x.collection?.actual||0)}</p>`).join('')||'<p>No completed work.</p>'}</details>${outboxView()}<nav class="rider-bottom-nav" aria-label="Rider sections"><a href="#/ride" data-local-section="local-ride-top"><span>↱</span><span>My route</span></a><a href="#/ride" data-local-section="local-ride-queue"><span>▤</span><span>Stops</span></a><a href="#/ride" data-local-section="local-ride-handover"><span>⇄</span><span>Handover</span></a></nav></div>`;}
  function wireNewForms(){
    const manual=$('#manual-form');
    if(manual){
      manual.querySelector('[name="payment"]').onchange=e=>{if(e.target.value==='prepaid')manual.querySelector('[name="expected"]').value='0';};
      manual.onsubmit=async e=>{e.preventDefault();const data=new FormData(manual),fields=Object.fromEntries(data);fields.expected=data.get('expected')===''?null:Number(data.get('expected'));const result=await submit('create_manual',{fields,received:data.has('received'),locationReviewed:data.has('locationReviewed'),createSeparate:data.has('createSeparate')},manual);if(result)go('order/'+result.value);};
    }
    const link=$('#customer-link-form');if(link)link.onsubmit=e=>{e.preventDefault();try{let value=String(new FormData(link).get('link')||'').trim();const match=value.match(/#\/?track\/([^?#\s]+)/);value=decodeURIComponent(match?match[1]:value);if(!value||!store.customer(value).available)throw Error('This delivery link is invalid, expired, revoked or locked. Ask the admin for a working link.');go('track/'+encodeURIComponent(value));}catch(err){failure(err,link);}};
  }
  function wireRider(){const picker=$('#rider-picker');if(picker)picker.onchange=e=>{actorKey=e.target.value;selected=null;render();};}
  function dialog(title,body,onSubmit,submitLabel='Confirm'){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.className='delivery-dialog functional-dialog';d.innerHTML=`<form><div class="kicker">LANNPYA LOCAL WORKSPACE</div><h2>${esc(title)}</h2>${body}${errorBox()}<div class="dialog-actions"><button type="button" class="btn" data-dismiss>Cancel</button><button class="btn green">${esc(submitLabel)}</button></div></form>`;document.body.append(d);d.showModal();const form=d.querySelector('form');form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const submitButton=form.querySelector('button[type="submit"], .btn.green');submitButton.disabled=true;try{if(scenario==='slow')await new Promise(r=>setTimeout(r,750));await onSubmit(new FormData(form));d.close();render();}catch(err){failure(err,form);}finally{busy=false;submitButton.disabled=false;}};d.querySelector('[data-dismiss]').onclick=()=>d.close();d.onclose=()=>d.remove();return d;}
  async function copyLink(id){const o=store.order(id,actor()),url=customerURL(tokenFor(o));if(store.linkStatus(id)!=='active')throw Error('Create an active link before copying.');try{await navigator.clipboard.writeText(url);toast('Link copied. Share it manually in the admin chat.');}catch{dialog('Copy this link manually',`<label>Customer link<input readonly value="${esc(url)}"></label><p>Clipboard access was unavailable. Select and copy this URL.</p>`,()=>{});}}
  function orderDialog(id,type){const o=store.order(id,actor());
    if(type==='location'){const area=W.PLACES.find(p=>p.id===o.areaId);if(!area)throw Error('Correct the supported township first.');dialog('Verify original location (fixture geography)',`<p>Demo ${area.name} rectangle: latitude ${area.bounds[0]}–${area.bounds[1]}, longitude ${area.bounds[2]}–${area.bounds[3]}. Coordinates below are a fixture reference, not proof of a real address.</p>${input('Latitude','lat',o.anchor?.lat||area.lat,'number','step="any" required')}${input('Longitude','lng',o.anchor?.lng||area.lng,'number','step="any" required')}${input('Location evidence / reason','reason','','text','required')}`,d=>cmd('verify_location',{id,pin:{lat:Number(d.get('lat')),lng:Number(d.get('lng'))},reason:d.get('reason'),expectedVersion:o.version}));}
    if(type==='assign'){const routes=store.snapshot().routes.filter(r=>r.state==='draft'&&r.date===o.date);if(!routes.length)throw Error('Create a draft route for this delivery day first.');dialog('Assign received eligible parcel',select('Draft route','routeId',routes.map(r=>({value:r.id,label:`${r.id} · ${r.riderId}`})),routes[0].id),d=>cmd('assign',{id,routeId:d.get('routeId'),expectedVersion:o.version}));}
    if(type==='cancel')dialog('Cancel / request return',`${input('Reason','reason','','text','required')}<label class="inline-check"><input type="checkbox" name="acknowledged"> Departed parcel: rider has acknowledged return instructions</label>`,d=>cmd('cancel',{id,reason:d.get('reason'),acknowledged:d.has('acknowledged'),expectedVersion:o.version}));
    if(type==='incident')dialog(o.incident?'Resolve incident':'Record incident',note('Incident or resolution reason','reason'),d=>cmd('incident',{id,reason:d.get('reason'),resolve:!!o.incident}));
    if(type==='discrepancy')dialog('Resolve collection discrepancy',`<p>Original expected ${amount(o.collection.expected)}; recorded ${amount(o.collection.actual)} remain unchanged.</p>${note('Resolution reason','reason')}`,d=>cmd('resolve_discrepancy',{id,reason:d.get('reason')}));
    if(type==='replan')dialog('New delivery cycle',input('Later delivery day','date',o.date,'date','required'),d=>cmd('replan',{id,date:d.get('date')}));
  }
  function cashDialog(id,type){
    const riderMode=type==='different-cash',a=riderActor(),r=store.snapshot().routes.find(r=>r.id===id),total=r.orderIds.map(id=>store.order(id)).reduce((s,o)=>s+(o.collection?.actual||0),0);
    const d=dialog(riderMode?'Hand over a different amount':'Receive cash & close route',`<p>Recorded collections: ${amount(total)}${r.handover?` · Rider declared: ${amount(r.handover.declared)}`:''}.</p>${riderMode?'':'<p>Count the physical cash before confirming. Saving receipt also closes this route if no issues remain.</p>'}${input(riderMode?'Amount handed over (MMK)':'Amount physically received (MMK)','amount',riderMode?r.handover?.declared??total:'','number','min="0" step="1" required')}<div id="cash-difference">${note('Reason for cash difference','reason',riderMode?r.handover?.reason||'':'')}${!riderMode?'<label class="inline-check"><input type="checkbox" name="resolve"> Difference investigated and resolved with the written reason</label>':''}</div>`,data=>{
      if(scenario==='save_failure')throw Error('Simulated save failure.');
      if(String(data.get('amount')??'').trim()==='')throw Error('Enter the amount you physically counted, including 0 for zero cash.');
      const result=store.execute(riderMode?'submit_cash':'receive_cash',{routeId:id,amount:Number(data.get('amount')),reason:data.get('reason'),resolve:data.has('resolve'),recordedTotal:riderMode?total:undefined,expectedDeclared:riderMode?undefined:r.handover?.declared,closeWhenReady:!riderMode},riderMode?a:actor());
      toast(riderMode?'Handover submitted — awaiting hub receipt.':result.value.closed?'Cash received and route closed.':'Cash receipt saved. Route stays open until the listed issues are resolved.');
      return result;
    },riderMode?'Submit handover':'Confirm receipt & close');
    const field=d.querySelector('[name="amount"]'),reason=d.querySelector('[name="reason"]'),difference=d.querySelector('#cash-difference');
    const update=()=>{const value=field.value.trim(),differs=value!==''&&(Number(value)!==total||!riderMode&&Number(value)!==r.handover?.declared);difference.hidden=!differs;reason.required=differs;};field.oninput=update;update();
  }
  function deliveryDialog(id){
    const a=riderActor(),o=store.order(id,a),saved=amountDrafts.get(id),draft=saved?.version===o.version?saved:null;
    const d=dialog(o.payment==='prepaid'?'Confirm prepaid handoff':'Record cash actually collected',`${draft?'<p class="notice">Unsubmitted amount draft restored. Nothing has been marked delivered yet.</p>':''}<div class="cod-amount">${amount(o.expected)}</div>${input('Actual cash collected (MMK)','amount',draft?.amount??o.expected,'number',`min="0" step="1" required ${o.payment==='prepaid'?'readonly':''}`)}${note('Required reason if actual differs from expected','reason',draft?.reason||'')}`,data=>{
      if(scenario==='save_failure')throw Error('Simulated save failure.');
      const result=store.execute('complete',{id,amount:Number(data.get('amount')),reason:data.get('reason'),expectedVersion:o.version},a,{offline:offline()});
      amountDrafts.delete(id);stashDrafts();toast(result.pending?'Handoff queued locally; pending replay.':'Handoff and cash recorded locally.');
    });
    d.querySelector('form').oninput=()=>{const data=new FormData(d.querySelector('form'));amountDrafts.set(id,{version:o.version,amount:data.get('amount'),reason:data.get('reason')});stashDrafts();};
  }
  function failDialog(id){const a=riderActor(),o=store.order(id,a);dialog('Record an unsuccessful attempt',select('Reason','reason',W.REASONS,W.REASONS[0])+select('Disposition','resolution',[{value:'retry',label:'Retry in a later window today'},{value:'return',label:'Return parcel to hub'}],'retry')+select('Future retry window (ignored for return)','time',W.WINDOWS,W.WINDOWS.at(-1)),d=>{if(scenario==='save_failure')throw Error('Simulated save failure.');store.execute('fail',{id,reason:d.get('reason'),resolution:d.get('resolution'),time:d.get('time'),expectedVersion:o.version},a,{offline:offline()});});}
  async function action(name,id,b){
    if(name==='sample'){window.batchRaw=W.SAMPLE;rows=[];render();}
    else if(name==='parse')await parseBatch();
    else if(name==='cancel-parse'){cancelParsing=true;toast('Unstarted parse rows will be cancelled.');}
    else if(name==='retry-row')await parseBatch(Number(id));
    else if(name==='commit-batch'){if(parsing)throw Error('Wait for parsing or cancel unstarted records.');const selectedRows=rows.filter(r=>r.status==='parsed'&&r.choice!=='skip');if(selectedRows.some(r=>r.duplicates.length&&r.choice!=='separate'))throw Error('Choose Skip or Create separately for each duplicate.');const result=cmd('create_batch',{records:selectedRows.map(r=>({raw:r.raw,duplicate:r.choice}))});const imported=new Set(selectedRows);rows=rows.filter(r=>!imported.has(r)&&r.choice!=='skip');window.batchRaw=rows.map(r=>r.raw).join('\n\n---\n\n');if(rows.length)render();else go('dispatch');toast(`${result.value.length} orders created. ${rows.length} unresolved draft records retained.`);}
    else if(['location','assign','cancel','incident','discrepancy','replan'].includes(name))orderDialog(id,name);
    else if(['receive','unassign','issue','shared','revoke','return-received'].includes(name)){const types={issue:'issue_link',revoke:'revoke_link','return-received':'return_received'};cmd(types[name]||name,{id});render();}
    else if(name==='copy')await copyLink(id);
    else if(name==='approve-location'){const o=store.order(id,actor());if(!o.proposedPin)throw Error('No customer point awaiting review.');dialog('Review customer-submitted location',`<p>Latitude ${esc(o.proposedPin.lat)}, longitude ${esc(o.proposedPin.lng)}. Confirm this is the correct parcel location before assignment.</p>${input('Review evidence / reason','reason','','text','required')}`,data=>cmd('approve_customer_location',{id,expectedVersion:o.version,reason:data.get('reason')}));}
    else if(name==='preview-location'){const a=W.PLACES.find(p=>p.id===id),form=$('#customer-form');if(!a||!form)return;form.querySelector('[name="latitude"]').value=a.lat;form.querySelector('[name="longitude"]').value=a.lng;form.oninput?.();toast('Approximate preview point selected. Admin review is still required.');}
    else if(name==='get-location'){const form=$('#customer-form');if(!navigator.geolocation||scenario==='no_gps')throw Error('GPS unavailable. Enter coordinates or ask the delivery admin for help.');navigator.geolocation.getCurrentPosition(position=>{if($('#customer-form')!==form)return;form.querySelector('[name="latitude"]').value=position.coords.latitude;form.querySelector('[name="longitude"]').value=position.coords.longitude;form.oninput?.();},()=>failure(Error('Location permission denied or unavailable. Enter coordinates manually.'),form),{timeout:10000,maximumAge:60000});}
    else if(name==='live-clock'){cmd('clock_live');render();}
    else if(name==='refresh-customer'){drafts.delete(id);stashDrafts();render();toast('Latest details loaded; unsaved draft discarded.');}
    else if(name==='new-route')dialog('Create rider route',select('Rider','riderId',Object.values(W.ACTORS).filter(a=>a.role==='rider').map(a=>({value:a.id,label:a.name})),'rider-1')+input('Delivery day','date',W.day(store.now()),'date','required'),d=>cmd('new_route',{riderId:d.get('riderId'),date:d.get('date')}));
    else if(name==='dispatch-route'){dialog('Confirm route departure','<p>Confirm all assigned parcels are physically present and the rider is ready to leave. Customer edits will be frozen.</p>',()=>cmd('dispatch',{routeId:id}));}
    else if(name==='ack-route'){store.execute('ack_route',{routeId:id},riderActor());render();}
    else if(name==='active'){const o=store.order(id,riderActor());store.execute('active_stop',{routeId:o.routeId,stopId:id},riderActor());render();}
    else if(name==='select-stop'){if(pending)throw Error('Undo or finish the current delivery first.');selected=id;render();}
    else if(name==='prepare-offline'){if(offline())throw Error('Reconnect before preparing a new offline queue.');store.execute('prepare_offline',{},riderActor());render();toast('Assigned queue prepared on this device.');}
    else if(name==='refresh-queue'){store.refresh();render();toast('Accepted local records refreshed.');}
    else if(name==='delivered'){if(pending){clearTimeout(timer);pending=null;render();return;}const o=store.order(id,riderActor());if(store.snapshot().outbox.some(q=>q.payload.id===id&&q.status!=='acknowledged'))throw Error('Review the pending action before recording another result.');pending={id};render();timer=setTimeout(()=>{pending=null;deliveryDialog(id);if(path.startsWith('ride'))render();},2000);}
    else if(name==='failed'){if(pending)throw Error('Undo or finish the current delivery first.');failDialog(id);}
    else if(name==='speak'){const o=store.order(id,riderActor());if(scenario==='no_voice'||!('speechSynthesis'in window))throw Error('Read aloud unavailable. Read the written landmark instead.');if(!o.landmark)throw Error('No landmark was supplied; review the street and verified coordinate.');const u=new SpeechSynthesisUtterance(o.landmark);u.lang='my-MM';u.onerror=()=>toast('Voice playback failed. Read the written landmark instead.');speechSynthesis.cancel();speechSynthesis.speak(u);}
    else if(name==='stop-speech'){if('speechSynthesis'in window)speechSynthesis.cancel();else toast('Audio is unavailable; the landmark is displayed as text.');}
    else if(name==='theme')document.body.classList.toggle('night');
    else if(name==='submit-cash'){const r=store.snapshot().routes.find(r=>r.id===id),total=r.orderIds.map(id=>store.order(id,riderActor())).reduce((sum,o)=>sum+(o.collection?.actual||0),0);await submit('submit_cash',{routeId:id,amount:total,recordedTotal:total},null);}
    else if(['different-cash','receive-cash'].includes(name))cashDialog(id,name);
    else if(name==='close-route'){cmd('close_route',{routeId:id});render();}
    else if(name==='replay'){if(offline())throw Error('Reconnect / turn off simulated offline before local replay.');if(scenario==='save_failure')throw Error('Simulated save failure.');store.replay();render();}
    else if(name==='resolve-outbox')dialog('Review preserved offline observation',note('Resolution reason','reason')+select('Disposition','accept',[{value:'yes',label:'Record observed handoff/attempt under admin review'},{value:'no',label:'Reject operation with audit reason'}],'no'),d=>store.resolvePending(id,d.get('reason'),d.get('accept')==='yes',actor()));
    else if(name==='stale'){const q=store.snapshot().outbox.find(q=>q.status==='pending');if(!q)throw Error('Queue a rider action offline first.');cmd('incident',{id:q.payload.id,reason:'Scenario: parcel changed while rider offline'});render();toast('Record version changed. Reconnect and replay to see conflict review.');}
    else if(name==='export'){const blob=new Blob([store.export()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='lannpya-workspace-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  }
  function wireActions(scope=document){scope.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{if(busy)return;try{await action(b.dataset.action,b.dataset.id,b);}catch(err){failure(err);}});scope.querySelectorAll('[data-row-raw]').forEach(el=>{el.oninput=()=>{const r=rows[Number(el.dataset.rowRaw)];r.raw=el.value;r.status='cancelled';delete r.fields;};el.onblur=paintPreview;});scope.querySelectorAll('[data-choice]').forEach(el=>el.onchange=()=>rows[Number(el.dataset.choice)].choice=el.value);}
  function wire(){wireActions();wireNewForms();const a=$('#actor-picker');if(a)a.onchange=e=>{actorKey=e.target.value;render();};const batch=$('#batch-raw');if(batch)batch.oninput=()=>window.batchRaw=batch.value;const edit=$('#edit-form');if(edit)edit.onsubmit=e=>{e.preventDefault();const d=new FormData(edit);const fields=Object.fromEntries(d);fields.expected=d.get('expected')===''?null:Number(d.get('expected'));fields.encodingReview=!d.has('unicodeReviewed');delete fields.unicodeReviewed;delete fields.reason;submit('edit',{id:edit.dataset.id,fields,reason:d.get('reason'),expectedVersion:Number(edit.dataset.version)},edit);};const policy=$('#policy-form');if(policy)policy.onsubmit=e=>{e.preventDefault();const d=new FormData(policy),[h,m]=d.get('cutoff').split(':').map(Number);submit('policy',{enforceCutoff:d.has('enforceCutoff'),areas:W.PLACES.filter(a=>d.has('area-'+a.id)).map(a=>a.id),cutoff:h*60+m,maxRetries:Number(d.get('maxRetries')),linkDays:Number(d.get('linkDays'))},policy);};const clock=$('#clock-form');if(clock)clock.onsubmit=e=>{e.preventDefault();submit('clock',{value:new FormData(clock).get('clock')+':00+06:30'},clock);};const scene=$('#scenario');if(scene)scene.onchange=e=>{scenario=e.target.value;toast('Scenario updated. Return to the relevant workflow.');};const off=$('#offline-mode');if(off)off.onchange=e=>{localOffline=e.target.checked;render();};}
  window.addEventListener('hashchange',()=>{if(pending){clearTimeout(timer);pending=null;}document.querySelector('dialog')?.close();render();});
  window.addEventListener('storage',e=>{if(e.key===W.KEY){store.refresh();if(pending||document.querySelector('dialog')||$('#customer-form'))toast('Workspace changed in another tab. Review the latest version before saving.');else render();}});
  window.addEventListener('online',()=>toast('Browser online. Pending rider actions still require local replay.'));
  window.addEventListener('offline',()=>toast('Browser offline. Customer confirmation requires reconnection; rider actions can queue locally.'));
  if(['http:','https:'].includes(location.protocol)&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline app shell could not be prepared. Local records are retained.'));
  render();
})();
